using System;
using System.Collections.Generic;
using System.IO;
using Unity.AI.Navigation;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.AI;
using UnityEngine.Rendering;
using UnityEngine.SceneManagement;
using Object = UnityEngine.Object;

/// <summary>Explicit, recovery-first installation. No environment or interface is generated by Play or recompilation.</summary>
public static class FacilityMenuInstaller
{
    private const string AssetRoot = "Assets/Generated/Interface";

    [MenuItem("Tools/Facility/Install Menus and Spawn Sandbox")]
    public static void Install()
    {
        if (EditorApplication.isPlayingOrWillChangePlaymode || Lightmapping.isRunning)
            throw new InvalidOperationException("Install menus outside Play mode and baking.");
        Scene scene = SceneManager.GetActiveScene();
        RetroFPSController player = FacilitySceneGenerator.FindInScene<RetroFPSController>(scene);
        FacilityHumanoid observer = FacilitySceneGenerator.FindInScene<FacilityHumanoid>(scene);
        GameObject facility = null;
        foreach (GameObject item in scene.GetRootGameObjects()) if (item.name == FacilitySceneGenerator.RootName) facility = item;
        if (player == null || observer == null || facility == null)
            throw new InvalidOperationException("Open the exploration scene with its original Player and authored observer first.");
        string recovery = AssetDatabase.GenerateUniqueAssetPath("Assets/Scenes/MenuRecovery_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".unity");
        if (!EditorSceneManager.SaveScene(scene, recovery, true)) throw new IOException("Recovery save failed; menu installation stopped.");
        foreach (string folder in new[] { AssetRoot, AssetRoot + "/Prefabs", AssetRoot + "/Materials", AssetRoot + "/Navigation" }) Folder(folder);
        foreach (GameObject item in scene.GetRootGameObjects())
            if (item.name == "Facility Game Systems") Object.DestroyImmediate(item);

        GameObject root = new GameObject("Facility Game Systems");
        SceneManager.MoveGameObjectToScene(root, scene);
        FacilityGameSession session = root.AddComponent<FacilityGameSession>();
        FacilitySpawnController spawner = root.AddComponent<FacilitySpawnController>();
        FacilityPlayerHealth health = player.GetComponent<FacilityPlayerHealth>();
        if (health == null) health = player.gameObject.AddComponent<FacilityPlayerHealth>();
        session.player = player; session.health = health; session.spawner = spawner;
        spawner.player = player; spawner.aimCamera = player.GetComponentInChildren<Camera>();
        spawner.validPreviewMaterial = PreviewMaterial("Placement Valid", new Color(.25f, .85f, .67f, .3f));
        spawner.invalidPreviewMaterial = PreviewMaterial("Placement Blocked", new Color(.9f, .2f, .12f, .26f));
        spawner.maxCharacters = 8;

        GameObject temporary = new GameObject("Temporary character prefab authoring");
        try
        {
            GameObject copy = Object.Instantiate(observer.gameObject, temporary.transform, false);
            copy.name = "The Observer"; copy.SetActive(false);
            copy.transform.localPosition = Vector3.zero; copy.transform.localRotation = Quaternion.identity;
            copy.GetComponent<FacilityHumanoid>().player = null;
            SubtleEnemyHealthBar copyBar = copy.GetComponentInChildren<SubtleEnemyHealthBar>(true);
            if (copyBar != null) copyBar.player = null;
            spawner.observerPrefab = PrefabUtility.SaveAsPrefabAsset(copy, AssetDatabase.GenerateUniqueAssetPath(AssetRoot + "/Prefabs/Observer.prefab"));
            GameObject zombie = FacilityZombieAuthoring.Build(observer, temporary.transform);
            spawner.zombiePrefab = PrefabUtility.SaveAsPrefabAsset(zombie, AssetDatabase.GenerateUniqueAssetPath(AssetRoot + "/Prefabs/Zombie.prefab"));
        }
        finally { Object.DestroyImmediate(temporary); }

        BuildNavigation(root, facility);
        FacilityMenuAuthoring.Build(root.transform, session);
        EditorUtility.SetDirty(player); EditorUtility.SetDirty(health); EditorUtility.SetDirty(spawner); EditorUtility.SetDirty(session);
        AssetDatabase.SaveAssets();
        var startup = new List<EditorBuildSettingsScene> { new EditorBuildSettingsScene(scene.path, true) };
        foreach (EditorBuildSettingsScene existing in EditorBuildSettings.scenes)
            if (existing.path != scene.path) startup.Add(new EditorBuildSettingsScene(existing.path, false));
        EditorBuildSettings.scenes = startup.ToArray();
        EditorSceneManager.MarkSceneDirty(scene);
        if (!EditorSceneManager.SaveScene(scene)) throw new IOException("Menu save failed. Recovery: " + recovery);
        Selection.activeGameObject = root;
        Debug.Log(Validate(scene) + " Recovery: " + recovery);
    }

    private static void BuildNavigation(GameObject systems, GameObject facility)
    {
        var sources = new List<NavMeshBuildSource>();
        NavMeshBuilder.CollectSources(facility.transform, ~0, NavMeshCollectGeometry.PhysicsColliders, 0, new List<NavMeshBuildMarkup>(), sources);
        NavMeshBuildSettings settings = NavMesh.GetSettingsByID(0);
        settings.agentHeight = 1.78f; settings.agentRadius = .36f; settings.agentClimb = .24f; settings.agentSlope = 45f;
        settings.overrideVoxelSize = true; settings.voxelSize = .06f;
        settings.overrideTileSize = true; settings.tileSize = 256; settings.minRegionArea = .7f;
        NavMeshData data = NavMeshBuilder.BuildNavMeshData(settings, sources, new Bounds(new Vector3(0, 4, 19), new Vector3(42, 18, 56)), Vector3.zero, Quaternion.identity);
        if (data == null) throw new InvalidOperationException("Facility navigation bake failed.");
        data.name = "Facility walking routes";
        AssetDatabase.CreateAsset(data, AssetDatabase.GenerateUniqueAssetPath(AssetRoot + "/Navigation/Facility Walking Routes.asset"));
        NavMeshSurface surface = systems.AddComponent<NavMeshSurface>();
        surface.collectObjects = CollectObjects.Volume;
        surface.center = new Vector3(0, 4, 19); surface.size = new Vector3(42, 18, 56);
        surface.useGeometry = NavMeshCollectGeometry.PhysicsColliders;
        surface.overrideVoxelSize = true; surface.voxelSize = .06f;
        surface.navMeshData = data;
        surface.AddData();
        EditorUtility.SetDirty(surface);
    }

    [MenuItem("Tools/Facility/Validate Menus and Spawn Assets")]
    public static void ValidateMenuCommand() => Debug.Log(Validate(SceneManager.GetActiveScene()));

    public static string Validate(Scene scene)
    {
        FacilityGameSession session = FacilitySceneGenerator.FindInScene<FacilityGameSession>(scene);
        if (session == null || session.spawner == null || session.player == null || session.health == null || session.canvas == null)
            throw new InvalidOperationException("Menu, spawner, health or original Player reference is missing.");
        foreach (Object item in new Object[] { session.mainMenu, session.pauseMenu, session.deathMenu, session.spawnMenu, session.hud, session.placementHud,
            session.hpText, session.healthFill, session.damageOverlay, session.placementText, session.spawnStatusText, session.spawnSelectionText,
            session.startButton, session.mainQuitButton, session.resumeButton, session.restartButton, session.pauseQuitButton,
            session.deathRestartButton, session.deathQuitButton, session.observerSpawnButton, session.zombieSpawnButton })
            if (item == null) throw new InvalidOperationException("An authored interface reference is missing.");
        foreach (GameObject prefab in new[] { session.spawner.observerPrefab, session.spawner.zombiePrefab })
        {
            if (prefab == null || !EditorUtility.IsPersistent(prefab) || prefab.activeSelf || prefab.GetComponent<FacilityHumanoid>() == null)
                throw new InvalidOperationException("Character templates must be saved, inactive humanoid prefabs.");
            if (prefab.GetComponent<FacilityHumanoid>().player != null) throw new InvalidOperationException("A prefab retains a scene Player reference.");
        }
        if (session.spawner.zombiePrefab.GetComponent<FacilityZombie>() == null) throw new InvalidOperationException("Zombie prefab has no melee/navigation behavior.");
        NavMeshSurface navigation = session.GetComponent<NavMeshSurface>();
        if (navigation == null || navigation.navMeshData == null || !EditorUtility.IsPersistent(navigation.navMeshData)) throw new InvalidOperationException("Saved navigation data is missing.");
        if (!NavMesh.SamplePosition(new Vector3(-2, .05f, 2), out NavMeshHit arrival, .3f, NavMesh.AllAreas))
            throw new InvalidOperationException("Arrival is absent from the baked walking routes.");
        Vector3[] route = {
            new Vector3(0, 0, 0), new Vector3(0, 0, 11), new Vector3(6, 0, 11), new Vector3(6, 0, 18),
            new Vector3(0, 0, 18), new Vector3(0, 3, 31), new Vector3(0, 3, 37), new Vector3(-12, 3, 37),
            new Vector3(-12, 3, 30), new Vector3(-12, 0, 21), new Vector3(-8, 0, 16), new Vector3(-12, 0, 6), new Vector3(-12, 0, 0)
        };
        var path = new NavMeshPath();
        for (int i = 0; i < route.Length; i++)
        {
            Vector3 next = route[(i + 1) % route.Length];
            if (!NavMesh.SamplePosition(route[i], out NavMeshHit from, .4f, NavMesh.AllAreas) ||
                !NavMesh.SamplePosition(next, out NavMeshHit to, .4f, NavMesh.AllAreas) ||
                !NavMesh.CalculatePath(from.position, to.position, NavMesh.AllAreas, path) || path.status != NavMeshPathStatus.PathComplete)
                throw new InvalidOperationException("Incomplete character navigation between " + route[i] + " and " + next + ".");
        }
        return "Menu validation passed: authored start/pause/death/spawn/HUD panels, two saved character prefabs, 3-hit player health, persistent navigation with 13 complete circuit links and original Player wiring.";
    }

    private static Material PreviewMaterial(string name, Color color)
    {
        string path = AssetRoot + "/Materials/" + name + ".mat";
        Material material = AssetDatabase.LoadAssetAtPath<Material>(path);
        if (material != null) return material;
        material = new Material(Shader.Find("Universal Render Pipeline/Unlit")) { name = name, enableInstancing = true };
        material.SetColor("_BaseColor", color);
        material.SetFloat("_Surface", 1); material.SetFloat("_Blend", 0); material.SetFloat("_ZWrite", 0);
        material.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha); material.SetFloat("_DstBlend", (float)BlendMode.OneMinusSrcAlpha);
        material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
        material.SetOverrideTag("RenderType", "Transparent"); material.renderQueue = (int)RenderQueue.Transparent;
        AssetDatabase.CreateAsset(material, path);
        return material;
    }

    private static void Folder(string path)
    {
        if (AssetDatabase.IsValidFolder(path)) return;
        string parent = path.Substring(0, path.LastIndexOf('/'));
        Folder(parent); AssetDatabase.CreateFolder(parent, path.Substring(path.LastIndexOf('/') + 1));
    }
}
